mapper.select:
SELECT A.PORTFOLIO_ID portfolioId, C.PTL_BAG_NAME portfolioName, A.IND_ID indId, B.IND_NAME indName, B.IND_TYPE indType, B.SUP_TYPE supType, B.WARN_COND warnCond, B.FOUL_COND foulCond, B.APPROVE_COND approveCond, B.IS_ENABLED isEnabled, A.PORTFOLIO_LEVEL portfolioLevel, A.START_DATE startDate, A.END_DATE endDate, D.PORTNAME as portfolioMix FROM RSK_PORTFOLIO_INDICATOR A LEFT JOIN RSK_ISUP_INDICATOR B on A.IND_ID=B.IND_ID LEFT JOIN RSK_PORTFOLIO_PACKAGE C on A.PORTFOLIO_ID=C.PTL_BAG_ID LEFT JOIN (select LISTAGG(n.PORTFOLIO_NAME, ',') WITHIN GROUP(ORDER BY n.PORTFOLIO_ID) as PORTNAME ,PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL m inner join PTL_PORTFOLIO n on m.PORTFOLIO_ID=n.PORTFOLIO_ID group by m.PTL_BAG_ID) D on A.PORTFOLIO_ID=D.PTL_BAG_ID
A.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
AND B.IND_NAME LIKE CONCAT(CONCAT('%',#{indName}),'%')
AND A.PORTFOLIO_LEVEL = #{portfolioLevel,jdbcType=VARCHAR}
AND B.SUP_TYPE = #{supType,jdbcType=VARCHAR}
